package protocol

import "testing"

// Golden vectors generated by running the ORIGINAL grokbot-headless JS
// cursorChecksum implementation under Node v26. These are ground truth; if the
// Go port ever diverges, the server-side checksum validation will fail.
func TestChecksumGolden(t *testing.T) {
	cases := []struct {
		machineID string
		nowMs     int64
		want      string
	}{
		{"mach-AAA", 0, "paaoq6-0mach-AAA"},
		{"mach-AAA", 1_000_000, "paWnqq60mach-AAA"},
		{"abc123", 1_700_000_000_000, "Vfb45Bi9abc123"},
		{"node-xyz", 1_761_480_000_000, "RY6QjXG-node-xyz"},
		{"", 2_000_000_000_000, "IaKkvT3C"},
	}
	for _, c := range cases {
		got := Checksum(c.machineID, c.nowMs)
		if got != c.want {
			t.Errorf("Checksum(%q, %d) = %q, want %q", c.machineID, c.nowMs, got, c.want)
		}
	}
}
